INSERT INTO content_missions (shift_id, direction_name, mission_name, description, key_steps, age_7_9, age_10_12, english_phrases, english_vocabulary, english_format, materials, criteria_0_3, criteria_4_6, criteria_7_8, criteria_9_10) VALUES
(1, 'СПОРТ', 'Нейрофитнес на Blazepod', 'Тренировка реакции и координации с LED-панелями Blazepod. Дети выполняют упражнения, реагируя на вспышки света.', 'Знакомство с тренажёром (3 мин); Разминка: простая реакция - хлопнуть при вспышке (5 мин); Основной блок: серия из 5 упражнений на скорость реакции (15 мин); Соревнование: кто быстрее наберёт максимум очков (10 мин); Фиксация результатов (5 мин)', 'Упрощённые комбинации (1-2 цвета), больше времени на каждое упражнение, акцент на веселье.', 'Сложные комбинации (3-4 цвета), замеры времени, соревновательный формат.', '"Ready? Go!", "Fast!", "Your turn!", "How many points?"', 'reaction, speed, challenge, score', 'вожатый даёт команды на английском, дети отвечают "I''m ready!"', 'Набор Blazepod (минимум 6 pod''ов); Мобильное приложение Blazepod; Таймер; Бланки результатов; Музыкальная колонка', 'Не включился в игру, не понял правила', 'Участвует с помощью вожатого, выполняет простые задания', 'Самостоятельно выполняет все упражнения, старается улучшить результат', 'Высокая скорость реакции, помогает другим, проявляет инициативу'),
(1, 'СПОРТ', 'Балансборды и стабильность', 'Работа на нестабильных платформах для укрепления мышц кора. Дети учатся удерживать равновесие.', 'Инструктаж по технике безопасности (3 мин); Знакомство с балансбордом: удержать равновесие 10 сек (5 мин); Упражнения: приседания, передача мяча, ходьба по линии (15 мин); Игра "Статуя": кто продержится дольше (10 мин); Запись личного рекорда (5 мин)', 'Балансборд на полу (без подушки), помощь вожатого, фокус на удержании позы.', 'Балансборд на нестабильной подушке, задания с закрытыми глазами, подбрасывание мяча.', '"Balance!", "Don''t fall!", "Hold it!", "Stand still!"', 'balance, steady, core, platform', 'вожатый считает на английском "One, two, three... ten!"', 'Балансборды (минимум 6, разного уровня); Нестабильные подушки (bosu); Мячи мягкие (для передачи); Малярный скотч (для разметки); Таймер; Бланки рекордов', 'Страх или отказ, не удерживает равновесие более 3 сек', 'Удерживает 10+ сек, выполняет базовые упражнения с поддержкой', 'Самостоятельно, удерживает 30+ сек', 'Сложные комбинации, помогает другим, ставит рекорды'),
(1, 'СПОРТ', 'Лазертаг-миссия', 'Командная тактическая игра в условиях "цифровой вселенной". Команды выполняют миссии: защита базы, захват территории.', 'Формирование команд (3 мин); Объяснение правил и безопасности (5 мин); Разведка и планирование стратегии (5 мин); Основная игра: 2-3 раунда по 8-10 минут (25 мин); Разбор тактики (5 мин)', 'Простые правила, больше подсказок, фокус на веселье.', 'Тактические задачи, командные роли (капитан, разведчик, снайпер).', '"Cover me!", "Go go go!", "I''m hit!", "Mission complete!"', 'mission, team, strategy, target, base', 'брифинг перед раундом на английском', 'Набор лазертаг (жилеты + пистолеты, мин. 12 комплектов); Разметка территории (конусы, стойки); Маскировочные элементы; Свистки; Аптечка; Музыка для атмосферы', 'Пассивный, прячется, не стреляет, не взаимодействует', 'Участвует, стреляет, но не планирует', 'Активно действует, общается с командой, предлагает тактику', 'Лидерство, координация, выполнение дополнительных миссий'),
(1, 'СПОРТ', 'Archery Tag', 'Стрельба из лука мягкими стрелами в формате соревнования. Дети учатся технике стрельбы.', 'Инструктаж по безопасности (5 мин); Обучение стойке и технике натяжения (5 мин); Тренировочная стрельба по мишеням (10 мин); Командное соревнование (15 мин); Финальный турнир (10 мин)', 'Лёгкий лук (10-12 фунтов), близкая дистанция (5 м), большие мишени.', 'Стандартный лук (14-16 фунтов), дистанция 8-10 м, движущиеся мишени.', '"Aim!", "Shoot!", "Bullseye!", "Nice shot!"', 'bow, arrow, target, aim, hit', 'техника объясняется на английском с русскими подсказками', 'Арчери-тэг набор (луки, мягкие стрелы, жилеты с мишенями); Мишени-стенды (мин. 6); Защитные очки; Разметка дистанции; Табло результатов; Аптечка', 'Не может натянуть лук, не соблюдает правила безопасности', 'Стреляет с помощью, попадает на близкой дистанции', 'Самостоятельно, попадает в 50%+, соблюдает технику', 'Высокая точность, помогает новичкам, спортсменский азарт'),
(1, 'СПОРТ', 'Мечевой бой', 'Современный фехтовальный бой с безопасным инвентарём. Дети изучают базовые приёмы атаки и защиты.', 'Знакомство с инвентарём и безопасность (5 мин); Базовые стойки и удары (10 мин); Упражнения в парах: атака-защита (10 мин); Турнирная сетка: поединки 1 на 1 (15 мин); Финал и награждение (5 мин)', 'Пенные мечи, акцент на защиту, правила "один удар - победа".', 'Полиуретановые мечи, система очков за зоны попадания, бои до 3 очков.', '"Fight!", "Stop!", "Guard!", "Attack!", "Good hit!", "Draw!"', 'sword, attack, defend, duel, champion', 'судейство на английском', 'Пенные/полиуретановые мечи (мин. 12); Защитные шлемы с сеткой (мин. 12); Накладки на руки; Разметка арены; Табло турнира; Эпик-музыка', 'Не соблюдает безопасность, бьёт запрещённые зоны', 'Соблюдает правила, участвует пассивно', 'Активно атакует и защищается, использует технику', 'Отличная техника, стратегия, спортсменское поведение'),
(1, 'IT', 'Программирование на micro:bit', 'Настройка сенсоров и первые шаги в коде на micro:bit. Программирование мини-компьютера.', 'Знакомство с micro:bit: части, кнопки, экран (5 мин); Первая программа: "Привет, мир!" (10 мин); Программирование кнопок: при нажатии - звук/свет (10 мин); Подключение датчика и вывод данных (10 мин); Демонстрация программы (5 мин)', 'Блоковый редактор MakeCode, готовые шаблоны, помощь вожатого.', 'Смешанный режим (блоки + JavaScript), собственные комбинации, переменные.', '"Code!", "Run the program!", "It works!", "Let''s try..."', 'code, program, sensor, button, LED', 'названия блоков в MakeCode на английском', 'micro:bit V2 (мин. 12 + запасные батарейки); USB-кабели; Компьютеры/планшеты с MakeCode; Датчики: температуры, освещённости, звука; Блоки питания / аккумуляторы AAA; Распечатанные инструкции-шпаргалки', 'Не смог подключить, не понял принцип блоков', 'Выполнил с помощью, запустил готовый шаблон', 'Самостоятельно собрал программу, подключил датчик', 'Создал оригинальную программу, экспериментировал, помогал другим'),
(1, 'IT', 'Сборка датчика-гаджета', 'Конструирование персонального устройства из электронных компонентов. Каждый собирает свой датчик.', 'Обзор компонентов (5 мин); Сборка схемы по инструкции (15 мин); Программирование: вывод данных на micro:bit (10 мин); Тестирование в разных условиях (5 мин); Оформление в корпус (5 мин)', 'Простая сборка (3-4 компонента), разъёмы без пайки, визуальные инструкции.', 'Сложная схема (5-6 компонентов), базовая пайка под присмотром, калибровка.', '"Connect the wire!", "It''s working!", "Measure the temperature!"', 'sensor, wire, measure, temperature, humidity', NULL, 'micro:bit (по одному); Датчики: DHT11, BH1750; Провода jumper wires; Платы-расширения; Пластиковые корпуса / картон; Инструкции', 'Не смог собрать, перепутал полярность', 'Собрал с помощью, работает нестабильно', 'Самостоятельно собрал и запрограммировал', 'Сложная конфигурация, калибровка, документирует результаты'),
(1, 'IT', 'Основы анализа данных', 'Сбор данных с датчиков и визуализация результатов. Измерение, запись, построение графиков.', 'Сбор данных: измерение в 5 точках территории (10 мин); Запись в таблицу (5 мин); Построение графика (10 мин); Анализ: где тепло, где тихо, где светло? (5 мин); Презентация findings на английском (10 мин)', 'Таблица из 5 ячеек, рисование графика фломастерами, устный анализ.', 'Google Sheets, автоматическое построение, письменный отчёт.', '"The temperature is...", "It''s warmer here!", "Look at the graph!"', 'data, graph, temperature, result', NULL, 'micro:bit с датчиками; Бланки таблиц; Фломастеры / цветные карандаши; Листы в клетку; Планшеты / компьютеры; Маркеры для точек измерения', 'Не записывает, не понимает зачем анализ', 'Заполняет с помощью, строит простой график', 'Самостоятельно собирает, записывает, анализирует', 'Точный анализ, находит закономерности, презентация на английском'),
(1, 'IT', 'Эко-полис: мини-проект', 'Проектирование элемента умного города с 3D-моделированием. Команда создаёт макет "умного" объекта.', 'Брейнсторминг: какой объект сделать "умным"? (5 мин); Эскиз и чертёж (10 мин); Сборка макета из подручных материалов + micro:bit (15 мин); Программирование "умной" функции (5 мин); Защита проекта (5 мин)', 'Готовые шаблоны, рисование + аппликация, простая программа.', 'Свободное проектирование, сложное программирование.', '"Our idea is...", "This is a smart bench", "It saves energy!"', 'smart, design, project, presentation', NULL, 'micro:bit + датчики; Картон, пенокартон, клей, ножницы, скотч; Краски, фломастеры; Пластилин / мини-фигурки; Принтер', 'Не участвует, не может объяснить идею', 'Участвует в команде, делает один элемент', 'Активно проектирует, рабочий макет', 'Оригинальная идея, работающий прототип, уверенная презентация'),
(1, 'БИОТЕХ', 'Биохакинг: пульс и реакция', 'Измерение реакции и пульса до и после физической нагрузки. Изучение реакции тела на активность.', 'Измерение пульса в покое (3 мин); Тест реакции (5 мин); Физическая нагрузка: приседания 1 минуту (3 мин); Повторное измерение (5 мин); Сравнение и выводы (10 мин)', 'Ручные измерения, рисунок "мое тело до и после".', 'Электронные пульсометры, табличные данные, расчёт % изменения.', '"My pulse is...", "After exercise...", "It''s faster!"', 'pulse, heart, exercise, rest, measure', NULL, 'Пульсометры / приложения; Тесты реакции; Бланки для данных; Секундомер; Коврики; Фломастеры', 'Отказывается измерять, не записывает', 'Измеряет с помощью, записывает', 'Самостоятельно, сравнивает данные', 'Точные измерения, анализирует изменения, объясняет группе'),
(1, 'БИОТЕХ', 'Анализ данных тела', 'Сравнение биометрических показателей участников. Работа с реальными данными.', 'Сбор данных у участников (10 мин); Заполнение сводной таблицы (5 мин); Построение "профиля атлета" (10 мин); Сравнительный анализ (5 мин); Выводы: каждый уникален (5 мин)', 'Графический "профиль атлета" (паучок), сравнение на глаз.', 'Табличные данные, расчёт средних, закономерности.', '"The fastest is...", "Average pulse is...", "Everyone is different!"', 'average, fastest, compare, result', NULL, 'Сводная таблица; Пульсометры; Рулетка; Весы; Бумага А3; Цветные карандаши', 'Не записывает, не анализирует', 'Помогает собирать, заполняет таблицу', 'Самостоятельно анализирует, строит профиль', 'Глубокий анализ, неочевидные связи, презентация'),
(1, 'БИОТЕХ', 'Эко-полис: зелёные технологии', 'Проектирование экологичных решений для умного города: солнечные панели, вертикальные сады, переработка.', 'Обсуждение экопроблем городов (5 мин); Мозговой штурм решений (10 мин); Создание макета / постера (15 мин); Расчёт экономии (5 мин); Презентация решения (5 мин)', 'Рисунок-постер + устное описание, работа в парах.', 'Поиск данных, расчёт экономии, сложные проекты.', '"Solar panels save energy!", "We can plant trees!", "Our solution is..."', 'environment, solar, recycle, energy', NULL, 'Бумага А2/А3; Фломастеры, цветные карандаши; Картон, ножницы, клей; Фото примеров зелёных технологий; Калькулятор; Планшеты', 'Не участвует, не может назвать экопроблему', 'Предлагает решение, рисует постер', 'Оригинальное решение, обоснование, качественный постер', 'Инновация с расчётом, уверенная презентация'),
(1, 'ПРЕДПРИНИМАТЕЛЬСТВО', 'Нейро-коины: внутренняя валюта', 'Заработок и управление игровой валютой через задания. Дети учатся зарабатывать и управлять "бюджетом".', 'Объяснение системы валюты (5 мин); "Магазин миссий": выбор заданий (5 мин); Выполнение заданий и получение коинов (15 мин); Ведение "бюджетной книжки" (5 мин); Обсуждение: копишь или тратишь? (5 мин)', 'Простая запись (галочки), вожатый помогает считать.', 'Таблица доходов/расходов, планирование бюджета.', '"I earned 5 coins!", "How much?", "I want to buy..."', 'coins, earn, spend, save, budget', NULL, 'Игровые монеты / фишки / наклейки; Бюджетные книжки (бланки); Прайс-лист миссий; Фломастеры; Конверты для коинов', 'Теряет коины, не ведёт запись', 'Ведёт запись с помощью, понимает ценность', 'Самостоятельно считает, планирует расходы', 'Экономическая стратегия, помогает другим'),
(1, 'ПРЕДПРИНИМАТЕЛЬСТВО', 'Питчинг гаджета', 'Защита проекта перед "инвестиционным комитетом". Представление датчика-гаджета.', 'Подготовка питча (10 мин); Репетиция (5 мин); Выступление (3 мин на человека); Вопросы "инвесторов" (2 мин); Обратная связь и награда (5 мин)', 'Рассказ с картинкой, 3-4 предложения, вожатый помогает.', 'Структурированный питч, ответы на вопросы.', '"Our gadget measures...", "It helps people because...", "Any questions?"', 'gadget, measure, useful, problem, solution', NULL, 'Собранные гаджеты; Макеты / рисунки; Таймер (3 мин); Бланки оценки; Награды', 'Не может объяснить, боится выступать', 'Рассказывает с помощью, отвечает на простые вопросы', 'Самостоятельный питч, структурированный', 'Уверенная презентация на английском, убедительная'),
(1, 'ПРЕДПРИНИМАТЕЛЬСТВО', 'Юнит-экономика продукта', 'Расчёт стоимости и ценности устройства. Считаем: материалы, время, ценность.', 'Подсчёт материалов: что использовали? Сколько стоит? (10 мин); Подсчёт времени (5 мин); Определение ценности (5 мин); Расчёт "прибыли" (5 мин); Обсуждение ценности (5 мин)', 'Простые числа (до 100), считаем вместе.', 'Табличные расчёты, понятие маржи.', '"It costs...", "We can sell it for...", "Profit is..."', 'cost, price, profit, value, worth', NULL, 'Калькуляторы; Бланки расчётов; Прайс-лист на материалы; Примеры реальных цен', 'Не понимает зачем считать', 'Считает с помощью, подставляет числа', 'Самостоятельно считает, понимает прибыль', 'Глубокий анализ, сравнение с реальными продуктами'),
(2, 'СПОРТ', 'Школа выживания', 'Базовые навыки ориентирования и пребывания на природе.', 'Знакомство с компасом (5 мин); Завязывание узлов (10 мин); Ориентирование по карте (10 мин); Строительство укрытия из подручных (10 мин); Запись в бортовой журнал (5 мин)', 'Простые узлы (2-3 вида), карта-рисунок, малый радиус.', 'Сложные узлы (5+), настоящая карта, широкий радиус.', '"Tie the knot!", "North is that way!", "Build a shelter!"', 'compass, knot, shelter, orient', NULL, 'Компасы (12+ шт), верёвки разной толщины; Карты территории, карточки узлов; Плёнка / ткань для укрытий, колья', 'Не может завязать узел, не ориентируется', 'Завязывает простые узлы, ориентируется с помощью', 'Самостоятельно, строит укрытие, находит точки', 'Все узлы, быстрое ориентирование, помогает другим'),
(2, 'СПОРТ', 'Верёвочный курс', 'Преодоление препятствий на высоте с элементами скалодрома.', 'Инструктаж по безопасности (5 мин); Разминка: растяжка (5 мин); Прохождение маршрута (20 мин); Замер времени (5 мин); Обсуждение техники (5 мин)', 'Низкая высота, страховка, простые элементы.', 'Выше, сложные переходы, соревнование.', '"Climb up!", "Hold tight!", "You can do it!", "Almost there!"', 'climb, hold, route, rope', NULL, 'Верёвочный парк / скалодром; Каски, страховочные систему; Перчатки, таймер', 'Страх, отказывается лезть', 'Проходит с помощью, простые элементы', 'Самостоятельно, сложные элементы', 'Быстро, помогает другим, разные маршруты'),
(2, 'СПОРТ', 'Захват флага', 'Командная тактическая игра за контроль территории.', 'Разведка территории (5 мин); Планирование стратегии (5 мин); Игра: 2 раунда по 10 минут (20 мин); Смена ролей (5 мин); Разбор тактики (5 мин)', 'Простые правила, больше подсказок, акцент на веселье.', 'Тактические задачи, роли (капитан, разведчик).', '"Go go go!", "Cover me!", "Got the flag!", "Defend!"', 'flag, capture, defend, strategy', NULL, 'Флаги (2 цвета), жилеты; Конусы для разметки территории; Свистки', 'Пассивный, не участвует', 'Участвует, но без стратегии', 'Активно действует, понимает роли', 'Лидерство, тактика, помогает команде'),
