-- Таблица content_missions — описания миссий для всех смен
-- ═══════════════════════════════════════════════════════════
CREATE TABLE IF NOT EXISTS content_missions (
  id               SERIAL PRIMARY KEY,
  shift_id         INTEGER NOT NULL,
  direction_name   TEXT NOT NULL,
  mission_name     TEXT NOT NULL,
  description      TEXT,
  key_steps        TEXT,
  age_7_9          TEXT,
  age_10_12        TEXT,
  english_phrases  TEXT,
  english_vocabulary TEXT,
  english_format   TEXT,
  materials        TEXT,
  criteria_0_3     TEXT,
  criteria_4_6     TEXT,
  criteria_7_8     TEXT,
  criteria_9_10    TEXT,
  created_at       TIMESTAMPTZ DEFAULT now()
);

-- Уникальный индекс по смене + направлению + миссии
CREATE UNIQUE INDEX IF NOT EXISTS idx_content_missions_unique
  ON content_missions (shift_id, direction_name, mission_name);

-- Публичный доступ на чтение (RLS)
ALTER TABLE content_missions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "Public read content_missions" ON content_missions;
CREATE POLICY "Public read content_missions" ON content_missions FOR SELECT USING (true);

-- ═══════════════════════════════════════════════════════════
--  SEED DATA
-- ═══════════════════════════════════════════════════════════

TRUNCATE TABLE content_missions;

